H=Path(__file__).resolve().parents[1];R=H/'results';read=lambda p:json.loads(p.read_text());a=read(R/'analysis.json');v=read(R/'oracle-all-points.json');e=read(R/'execution-summary.json');axes=read(H/'axes.json')['groups'];old=(H/'record.md').read_text();out=[]
